"""Build five independent direction studies. No production imports or analysis runs."""
from pathlib import Path
import html,json,math

ROOT=Path(__file__).resolve().parent
REPO=ROOT.parents[1]
data=json.loads((REPO/'validation/regression/reports/bike_hour.json').read_text())
bins=data['profile']['regression']['target_statistics']['histogram']['bins']
esc=html.escape
arrow='<span class="arrow" aria-hidden="true">↗</span>'
mark='<svg viewBox="0 0 28 28" aria-hidden="true"><path fill="currentColor" d="M1 25V3h6l14 16V3h6v22h-6L7 9v16z"/></svg>'
brand=f'<span class="brand">{mark}numek</span>'

def plot(variant='',width=580,height=210):
    W=580;H=210;s=f'<svg class="plot {variant}" viewBox="0 0 580 210" role="img" aria-label="Bike Sharing target distribution. 40 bins over 17,379 finite targets; median 142; maximum bin count 3,377.">'
    for n in [0,1000,2000,3000]:
        y=173-n/3500*146;s+=f'<path class="grid" d="M34 {y:.2f}H568"/><text x="0" y="{y+3:.2f}">{n if n<1000 else str(n//1000)+"k"}</text>'
    for i,b in enumerate(bins):
        x=34+i*534/40;h=b['count']/3500*146;y=173-h
        s+=f'<rect class="bar" x="{x:.2f}" y="{y:.2f}" width="{534/40-3:.2f}" height="{h:.2f}" rx=".7"><title>{b["lower"]:.1f}–{b["upper"]:.1f}: {b["count"]:,} rows</title></rect>'
    mx=34+(142-1)/976*534
    s+=f'<path class="median" d="M{mx:.2f} 23V173"/><text x="{mx+7:.2f}" y="20">Median 142</text><text x="34" y="195">1</text><text x="153" y="195">250</text><text x="290" y="195">500</text><text x="427" y="195">750</text><text x="548" y="195">977</text><text x="1" y="13">Rows</text></svg>'
    return s

def table(klass='',count=3):
    rows=[(1,3,13,16),(2,8,32,40),(3,5,27,32),(4,3,10,13),(5,0,1,1)]
    s=f'<table class="data-table {klass}"><caption>Exact source examples · Parsed row references</caption><thead><tr><th>Row</th><th>casual</th><th>registered</th><th>cnt</th></tr></thead><tbody>'
    for row in rows[:count]:s+='<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>'
    return s+'</tbody></table>'

def tabs(prefix,labels=('Overview','Finding & evidence')):
    return f'<div class="product-tabs" data-tab-group role="tablist" aria-label="Example analysis views"><button class="product-tab" role="tab" id="{prefix}-tab-home" aria-selected="true" aria-controls="{prefix}-home">{labels[0]}</button><button class="product-tab" role="tab" data-result id="{prefix}-tab-result" aria-selected="false" aria-controls="{prefix}-result" tabindex="-1">{labels[1]}</button></div>'

def panel(prefix,which,body):
    return f'<div class="panel" role="tabpanel" id="{prefix}-{which}" aria-labelledby="{prefix}-tab-{"home" if which=="home" else "result"}" {"hidden" if which!="home" else ""}>{body}</div>'

def note(n,title,presentation,product,refs):
    return f'<section class="study-notes" id="approach"><div><small>Direction {n} / round two</small><h2>{title}</h2></div><div><h3>What makes it NUMEK</h3><p>{presentation}</p></div><div><h3>How it becomes a product</h3><p>{product}</p></div></section><footer class="lab-note"><p><b>Creative-direction study.</b> Full opening, a live interaction and an application/result treatment. Complete landing pages and three-screen prototypes await direction approval.</p><p>Observed craft: {refs}<br><span>Original NUMEK graphics. Example evidence comes from existing local regression fixtures.</span></p></footer>'

def write(n,title,body):
    dialog='<dialog id="method-dialog" class="dialog"><button type="button" data-close-dialog>Close</button><h2>What the evidence says.</h2><p>In the stored Bike Sharing regression report, <code>cnt = casual + registered</code> holds over all 17,379 overlapping rows. The two component inputs are declared unavailable at prediction time.</p><p>Observed equality and supplied availability do not establish actual model use or prove leakage. Review collection timing, derivation and the intended input set.</p><p>No universal regression reliability score is defined. Source: <code>validation/regression/reports/bike_hour.json</code>.</p></dialog>'
    (ROOT/(n+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="NUMEK / DataTrust — revised visual direction {n}. Local design study."><title>{title} — NUMEK direction {n}</title><link rel="stylesheet" href="base.css"><link rel="stylesheet" href="{n}.css"></head><body>{body}{dialog}<script type="module" src="interactions.js"></script></body></html>')

