body=f'''<header class="a-header"><a href="01.html" aria-label="NUMEK home">{brand}</a><nav class="navlinks"><a href="#product">DataTrust</a><a href="#approach">Our approach</a><a href="#product" class="a-nav-cta">Explore the product {arrow}</a></nav></header><main><section class="a-hero"><div class="a-hero-meta"><span>AI reliability, before the model.</span><span><i class="dot"></i>Introducing DataTrust</span></div><h1>SEE WHAT<br>YOU’RE BUILDING ON.</h1><div class="a-stage" data-tilt><div class="a-backing a-backing-one"><span>17,379 source rows</span></div><div class="a-backing a-backing-two"><span>49 completed applicable checks</span></div>{hero_app}<button class="a-sticker" type="button" data-align aria-label="Align the evidence layers" aria-pressed="false"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 20h30M20 5v30M9 9l22 22M9 31L31 9" stroke="currentColor" stroke-width="3"/></svg><span>Evidence.<br>In full view.</span></button></div><div class="a-hero-bottom"><p>Local dataset analysis. Inspectable findings.<br>A clearer basis for your next decision.</p><a href="#product">Take a closer look <span>↓</span></a></div></section><section class="a-intro"><h2>Go beyond a summary.<br>Get to the substance.</h2><p>DataTrust connects the finding to the data behind it. Explore distributions, inspect exact evidence and understand the limits of each analysis.</p></section><section class="a-product" id="product" data-product><div class="product-label"><span>DataTrust / Application study</span><span>01 — In full view</span></div><div class="a-product-bar"><span class="a-product-word">{mark}DataTrust</span><span>Local workspace</span><button class="sheet-action" data-method>Method & coverage</button></div>{tabs('a')}'''
body+=panel('a','home',f'''<div class="a-app-layout"><div><div class="a-app-heading"><div><span class="tiny">Regression / Example analysis</span><h3>Bike Sharing</h3></div><span class="a-complete"><i class="dot"></i>Evidence available</span></div><div class="a-app-stats"><div><strong>17,379</strong><span>Rows examined</span></div><div><strong>17</strong><span>Supplied columns</span></div><div><strong>4</strong><span>Prioritized findings</span></div></div><div class="a-large-chart"><h4>What does the target look like?</h4>{plot()}<p class="method-note">Finite target distribution / count of rental bikes per interval</p></div></div><aside><h4>What to investigate</h4><button class="a-finding" data-inspect="#product"><span class="a-severity">High</span><strong>Review input availability</strong><p>casual and registered are declared unavailable at prediction time.</p><span>View supporting evidence {arrow}</span></button><div class="a-finding-secondary"><span class="tiny">Also in this report</span><p>Supported target relationship</p><p>IQR review candidates</p><p>Near-constant fields</p></div></aside></div>''')
body+=panel('a','result',f'''<div class="a-result-layout"><div><span class="a-severity">Finding / target relationship</span><h3>The total is already<br>in the inputs.</h3><p class="a-result-summary">One supported arithmetic identity across the full observed overlap.</p><div class="a-equation-large">cnt <span>=</span> casual <span>+</span> registered</div>{table(count=5)}</div><aside><h4>17,379 / 17,379</h4><p>Overlapping rows supporting the identity.</p><hr><h4>What this means</h4><p>Review feature timing and derivation against the intended prediction time.</p><p>Observed algebra alone does not prove leakage or actual model use.</p><button class="source-button" data-method>Read the method and limitations</button><span class="method-note">Evidence / regression_relationship.44</span></aside></div>''')
body+='</section></main>'+note('01','In full view.','Large typography gives way to a readable analytical surface. The product carries the visual identity; the floating layers are source, check coverage and the resulting investigation.','A compact navigation rail, wide analysis surface and contextual evidence panel. The dramatic entry resolves into quiet, aligned software.','<a href="https://sonsanddaughters.xyz/">Sons & Daughters</a> — small subject to expansive view; <a href="https://micro.reformcollective.com/">Micro</a> — product staging.')
